import sys,re,json,collections
sys.path.insert(0,'/tmp/claude-0/-home-user-fortress/fe616d40-a9c6-56d7-9da1-7168a172765d/scratchpad/archaeology')
from load import load
recs=load()
byn={r['n']:r for r in recs}
bounds=[r for r in recs if r['t']=='system' and r.get('sub')=='compact_boundary']
# issuing call per tool_use id
tu={}
for r in recs:
    if r['t']=='assistant':
        for b in r['b']:
            if b[0]=='tu': tu[b[1]]=(r['n'],b[2],b[3],r['mid'])
# API calls sequence: assistant mids in order, with pt
calls=[]  # (n_first, mid, pt)
seen=set()
for r in recs:
    if r['t']=='assistant' and r['mid'] not in seen:
        seen.add(r['mid']); calls.append((r['n'],r['mid'],r.get('pt')))
callidx={c[1]:i for i,c in enumerate(calls)}
# output tokens per mid is not stored; approximate: sum of text/tu chars/4
outtok={}
for r in recs:
    if r['t']=='assistant':
        L=0
        for b in r['b']:
            if b[0]=='text': L+=len(b[1])
            elif b[0]=='tu': L+=len(json.dumps(b[3]))
        outtok[r['mid']]=outtok.get(r['mid'],0)+L/3.5
def step_tokens(tuid):
    n,name,inp,mid=tu[tuid]
    i=callidx[mid]
    if i+1>=len(calls): return None
    pt0=calls[i][2]; pt1=calls[i+1][2]
    if pt0 is None or pt1 is None: return None
    return pt1-pt0-int(outtok.get(mid,0)), calls[i+1][0]
INDEXPAT=re.compile(r'^\s*(\d+\t)?- `[^`]*\.(md|txt|py|sh|tic|json|fss|fsi|jsonl)`: ',re.M)
def index_reads():
    out=[]
    for r in recs:
        if r['t']!='user': continue
        for b in r['b']:
            if b[0]=='tr':
                m=INDEXPAT.findall(b[2])
                if len(m)>=20 and b[1] in tu:
                    out.append((r['n'],b[1],len(m),len(b[2])))
    return out
if __name__=='__main__':
    print(len(bounds))
    ir=index_reads()
    # group by boot
    bn=[b['n'] for b in bounds]
    import bisect
    groups=collections.defaultdict(list)
    for x in ir:
        k=bisect.bisect_right(bn,x[0])-1
        groups[k].append(x)
    for k,b in enumerate(bounds):
        g=groups.get(k,[])
        steps={}
        for x in g:
            st=step_tokens(x[1])
            steps.setdefault(tu[x[1]][3],[]).append((x,st))
        tot_chars=sum(x[3] for x in g)
        # distinct steps tokens
        toks=0
        for mid,l in steps.items():
            st=l[0][1]
            if st: toks+=st[0]
        print(k,b['n'],b['ts'][5:16],'pre',b['txt'][b['txt'].find('preTokens'):][:20] if False else '', 'calls',len(g),'chars',tot_chars,'tokens(step-delta)',toks,'first',g[0][0] if g else None,byn[g[0][0]]['ts'][11:19] if g else '', 'matches',sum(x[2] for x in g))
EOF
python3 -I boots.py

