import sys,bisect
sys.path.insert(0,'/tmp/claude-0/-home-user-fortress/fe616d40-a9c6-56d7-9da1-7168a172765d/scratchpad/archaeology')
from boots import *
BOOTFILES=['BOOT.md','HELD.md','INDEX.md','FACTS.md','POSITIONS.md','PLAN.md','check-index','git log','protocol.md','SKILL.md','README.md','/idx','/pos','/f1','/f7','tool-results/','explorations/coordinator/','references/','CLAUDE.md','pos-','idx-','boot/','get_session']
ir=index_reads()
irset={x[1] for x in ir}
res_len={}
for r in recs:
    if r['t']=='user':
        for b in r['b']:
            if b[0]=='tr': res_len[b[1]]=len(b[2])
bn=[b['n'] for b in bounds]
out=[]
for k,b in enumerate(bounds):
    end_n=bn[k+1] if k+1<len(bn) else 10**9
    # calls in window
    wc=[(i,c) for i,c in enumerate(calls) if b['n']<c[0]<end_n]
    first=wc[0]
    # last boot-read call among first 40 calls
    last=None
    for i,c in wc[:45]:
        r=byn[c[0]]
        # tool uses of this mid
        hit=False
        for rr in recs:
            pass
        out_tus=[v for v in tu.values() if v[3]==c[1]]
        for (nn,name,inp,mid) in out_tus:
            s=str(inp)
            if any(f in s for f in BOOTFILES) and name in('Read','Bash','Grep'):
                hit=True
        if hit: last=(i,c)
    base=first[1][2]
    endpt=None
    # prompt size after last boot call's results = next call's pt
    if last:
        nxt=calls[last[0]+1]
        endpt=nxt[2]
    idxtok=sum(res_len[x[1]] for x in ir if b['n']<x[0]<end_n)*0.371
    out.append((k,b['n'],b['ts'][5:16],base,endpt,(endpt-base) if endpt else None,round(idxtok),round(idxtok/(endpt-base),2) if endpt else None, last[0]-first[0]+1 if last else None))
for o in out: print(o)
EOF
python3 -I share.py

