    elif r['t']=='user' and any(b[0]=='tr' for b in r['b']): last_text=None
    elif r['t']=='system' and r.get('sub')=='stop_hook_summary':
        if last_text: final_text.add(last_text[0])
        last_text=None
uses=[]
for r in recs:
    if r['t']!='assistant': continue
    n=r['n']
    for b in r['b']:
        if b[0]=='text':
            ps=strict_paths(b[1])
            for p in ps: uses.append(dict(n=n,ts=r['ts'],kind='text-final' if n in final_text else 'text',tool='text',p=p))
        elif b[0]=='tu':
            name,inp=b[2],b[3]
            if name=='Read':
                fp=inp.get('file_path','')
                for p in strict_paths(fp): uses.append(dict(n=n,ts=r['ts'],kind='open',tool='Read',p=p))
            elif name=='Grep':
                for p in strict_paths(json.dumps(inp)): uses.append(dict(n=n,ts=r['ts'],kind='open',tool='Grep',p=p))
            elif name=='Bash':
                c=inp.get('command','')
                ps=strict_paths(c)
                if not ps: continue
                if 'facts-extract' in c:
                    kind='open' if re.search(r'doc:|map:',c) else 'search'
