                kind='open' if (rd and not w) else ('open?' if rd and w else 'write')
                for p in ps: uses.append(dict(n=n,ts=r['ts'],kind=kind,tool='Bash',p=p,cmd=c[:200].replace('\n',' ')))
            elif name in('Agent','Workflow','SendMessage'):
                txt=json.dumps(inp) if name!='Agent' else inp.get('prompt','')
                for p in strict_paths(txt): uses.append(dict(n=n,ts=r['ts'],kind='brief',tool=name,p=p))
            elif name=='Write':
                fp=inp.get('file_path','')
                if strict_paths(fp): continue   # writing the note itself
                for p in strict_paths(inp.get('content','')): uses.append(dict(n=n,ts=r['ts'],kind='brief',tool='Write',p=p,file=fp))
# classify
for u in uses:
    k=bisect.bisect_right(bn,u['n'])-1
    u['k']=k
    ear=[c for c in carriers if bn[k]<c[0]<u['n'] and u['p'] in c[2]]
    loose=[c for c in carriers if bn[k]<c[0]<u['n'] and u['p'] in c[3]]
    cl=collections.Counter(c[1] for c in ear)
    u['carriers']=dict(cl)
    u['first']=min(((c[0],c[1]) for c in ear),default=None)
    a=[x for x in ear if x[1] not in('INDEX','search')]
    if a: u['cls']='a'; u['via']=min((x[0],x[1]) for x in a)
    elif any(x[1]=='search' for x in ear): u['cls']='c'; u['via']=min((x[0],x[1]) for x in ear if x[1]=='search')
    elif ear: u['cls']='b'; u['via']=ear[0][:2]
    else: u['cls']='d'; u['via']=None
    u['loose']=[(x[0],x[1]) for x in loose if x[1] not in('INDEX',)][:3]
pickle.dump(uses,open('uses.pkl','wb'))
c=collections.Counter((u['kind'],u['cls']) for u in uses)
for k,v in sorted(c.items()): print(k,v)
print(len(uses))
