from uses import *
uses=pickle.load(open('uses.pkl','rb'))
def input_text(n):
    r=byn[n]; out=[]
    for b in r['b']:
        if b[0]=='tu':
            out.append(b[2]+': '+(b[3].get('command') or b[3].get('prompt') or b[3].get('content') or json.dumps(b[3])))
        elif b[0]=='text': out.append('TEXT: '+b[1])
    return '\n'.join(out)
def snip(n,p,w=150):
    t=input_text(n)
    base=p.split('/')[-1]
    out=[]
    for m in re.finditer(re.escape(base),t):
        s=max(0,m.start()-w); e=min(len(t),m.end()+w)
        out.append(t[s:e].replace('\n',' '))
        if len(out)>=2: break
    return out
if __name__=='__main__':
    ns=[int(x) for x in sys.argv[1:]]
    for u in uses:
        if u['cls']=='b' and u['n'] in ns and u['kind'] in('open','open?','brief','text-final','text','search'):
            print('##',u['k'],u['n'],u['kind'],u['p'].replace('explorations/',''))
            for s in snip(u['n'],u['p']): print('   ..',s)
